1	package fleet
2	
3	import (
4		"crypto/rand"
5		"encoding/binary"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"hash/crc32"
10		"io"
11		"io/fs"
12		"os"
13		"path/filepath"
14		"sync"
15		"syscall"
16		"time"
17	)
18	
19	// Persistent mode stores every acknowledged mutation as one checksummed record
20	// in an append-only write-ahead log. A record is the commit unit: either the
21	// whole record is durable (and visible after recovery) or none of it is, so a
22	// replay batch can never leave half of its samples behind.
23	//
24	// Commit protocol per write (WAL frame and commit journal are separate files so
25	// the commit decision never depends on parsing a possibly torn frame length):
26	//
27	//  1. write the frame at the committed offset and fsync the WAL;
28	//  2. append a fixed-size entry carrying the new committed WAL length to the
29	//     commit journal and fsync it;
30	//  3. only then report success.
31	//
32	// Recovery reads the committed length T from the journal, verifies that WAL
33	// bytes [header, T) form an exact chain of valid frames, applies them, and
34	// treats bytes (T, EOF] as the residue of an unacknowledged write. Damage to
35	// committed bytes always fails startup instead of being trimmed away.
36	
37	const (
38		walName     = "wal.log"
39		commitName  = "commit.log"
40		lockName    = "lock"
41		walMagic    = "EDGEFLET" // 8 bytes
42		headerLen   = 16         // magic(8) + version(4) + flags(4)
43		walVersion  = 1
44		commitEntry = 12 // [committed WAL length uint64 LE][crc32 LE]
45	
46		// maxRecordPayload bounds a single frame; HTTP bodies are capped at 1MiB so
47		// this only rejects absurd length fields from damaged files.
48		maxRecordPayload = 8 << 20
49	)
50	
51	const (
52		recInstance byte = 1 + iota
53		recRegister
54		recTelemetry
55		recReplay
56	)
57	
58	// ErrStorageUnavailable wraps a durable-write failure at runtime. A request
59	// that fails this way never mutated queryable state.
60	var ErrStorageUnavailable = errors.New("storage unavailable")
61	
62	var crcTable = crc32.MakeTable(crc32.Castagnoli)
63	
64	// walSink is the commit log behind a persistent store.
65	type walSink interface {
66		appendRecord(recType byte, value any) error
67	}
68	
69	type walInstance struct {
70		InstanceID []byte `json:"instanceId"`
71	}
72	
73	type walRegister struct {
74		ID           string    `json:"id"`
75		Site         string    `json:"site"`
76		RegisteredAt time.Time `json:"registeredAt"`
77		LastSeenAt   time.Time `json:"lastSeenAt"`
78	}
79	
80	type walTelemetry struct {
81		DeviceID   string             `json:"deviceId"`
82		Sequence   int64              `json:"sequence"`
83		ObservedAt time.Time          `json:"observedAt"`
84		Values     map[string]float64 `json:"values"`
85	}
86	
87	type walSample struct {
88		EventID    string             `json:"eventId"`
89		ObservedAt time.Time          `json:"observedAt"`
90		Values     map[string]float64 `json:"values"`
91	}
92	
93	// walReplay is one committed batch. Samples holds the full ordered batch
94	// (duplicates included) and Receipt the first-acceptance receipt; new events
95	// and their sequences are derived by zipping the two during recovery.
96	type walReplay struct {
97		DeviceID      string             `json:"deviceId"`
98		BatchID       string             `json:"batchId"`
99		Samples       []walSample        `json:"samples"`
100		Receipt       ReplayReceipt      `json:"receipt"`
101		LastSeenAt    *time.Time         `json:"lastSeenAt,omitempty"`
102		LastTelemetry map[string]float64 `json:"lastTelemetry,omitempty"`
103	}
104	
105	// walFile is the durable backend. walDurable is the committed WAL length (also
106	// the next frame offset); commitDurable is the journal length. Both files are
107	// truncated back to those offsets before every write, so residue left by a
108	// failed write can never be mistaken for later committed data.
109	type walFile struct {
110		walF          *os.File
111		commitF       *os.File
112		lock          *os.File
113		mu            sync.Mutex
114		walDurable    int64
115		commitDurable int64
116	}
117	
118	func (w *walFile) appendRecord(recType byte, value any) error {
119		frame, err := marshalFrame(recType, value)
120		if err != nil {
121			return err
122		}
123		w.mu.Lock()
124		defer w.mu.Unlock()
125	
126		// Remove residue any previous failed attempt may have left, then phase 1.
127		if err := w.walF.Truncate(w.walDurable); err != nil {
128			return err
129		}
130		if err := pwriteAll(w.walF, frame, w.walDurable); err != nil {
131			return err
132		}
133		if err := w.walF.Sync(); err != nil {
134			return err
135		}
136	
137		// Phase 2: publish the new committed length in the fixed-width journal.
138		newLength := w.walDurable + int64(len(frame))
139		entry := make([]byte, commitEntry)
140		binary.LittleEndian.PutUint64(entry[0:8], uint64(newLength))
141		binary.LittleEndian.PutUint32(entry[8:12], commitCRC(entry[0:8]))
142		if err := w.commitF.Truncate(w.commitDurable); err != nil {
143			return err
144		}
145		if err := pwriteAll(w.commitF, entry, w.commitDurable); err != nil {
146			return err
147		}
148		if err := w.commitF.Sync(); err != nil {
149			return err
150		}
151	
152		w.walDurable = newLength
153		w.commitDurable += int64(commitEntry)
154		return nil
155	}
156	
157	func commitCRC(sizeBytes []byte) uint32 {
158		return crc32.Checksum(sizeBytes, crcTable)
159	}
160	
161	func pwriteAll(f *os.File, buf []byte, offset int64) error {
162		for len(buf) > 0 {
163			n, err := f.WriteAt(buf, offset)
164			if err != nil {
165				return err
166			}
167			buf = buf[n:]
168			offset += int64(n)
169		}
170		return nil
171	}
172	
173	func (w *walFile) Close() error {
174		walErr := w.walF.Close()
175		commitErr := w.commitF.Close()
176		// Closing the lock fd releases the flock; a killed process releases it via
177		// the kernel, so no manual lock cleanup is ever required.
178		lockErr := w.lock.Close()
179		if walErr != nil {
180			return walErr
181		}
182		if commitErr != nil {
183			return commitErr
184		}
185		return lockErr
186	}
187	
188	// NewPersistentStore opens (or creates) a data directory and finishes full
189	// recovery before returning. It fails rather than falling back to memory when
190	// the directory cannot be created, locked, read or written, when another
191	// process already holds the directory, or when committed data is corrupt or
192	// in an unsupported format.
193	func NewPersistentStore(dir string) (_ *Store, err error) {
194		if fi, statErr := os.Stat(dir); statErr == nil {
195			if !fi.IsDir() {
196				return nil, fmt.Errorf("data path %s is not a directory", dir)
197			}
198		} else if !errors.Is(statErr, fs.ErrNotExist) {
199			return nil, fmt.Errorf("cannot access data directory %s: %w", dir, statErr)
200		}
201		if err := os.MkdirAll(dir, 0o755); err != nil {
202			return nil, fmt.Errorf("cannot create data directory %s: %w", dir, err)
203		}
204	
205		// Take the inter-process lock before reading or writing any business data.
206		lockPath := filepath.Join(dir, lockName)
207		lockFile, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
208		if err != nil {
209			return nil, fmt.Errorf("cannot open lock file %s: %w", lockPath, err)
210		}
211		if lockErr := syscall.Flock(int(lockFile.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); lockErr != nil {
212			_ = lockFile.Close()
213			return nil, fmt.Errorf("data directory %s is already in use by another edge-fleet process: %w", dir, lockErr)
214		}
215		handedOff := false
216		defer func() {
217			if !handedOff {
218				_ = lockFile.Close()
219			}
220		}()
221	
222		walPath := filepath.Join(dir, walName)
223		commitPath := filepath.Join(dir, commitName)
224		walF, err := os.OpenFile(walPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
225		if err != nil {
226			return nil, fmt.Errorf("cannot open write-ahead log %s: %w", walPath, err)
227		}
228		commitF, err := os.OpenFile(commitPath, os.O_RDWR|os.O_CREATE|syscall.O_CLOEXEC, 0o600)
229		if err != nil {
230			_ = walF.Close()
231			return nil, fmt.Errorf("cannot open commit journal %s: %w", commitPath, err)
232		}
233		committed := false
234		defer func() {
235			if !committed {
236				_ = walF.Close()
237				_ = commitF.Close()
238			}
239		}()
240	
241		walInfo, err := walF.Stat()
242		if err != nil {
243			return nil, fmt.Errorf("cannot stat write-ahead log %s: %w", walPath, err)
244		}
245		if walInfo.Size() == 0 {
246			if _, err := walF.WriteAt(walHeader(), 0); err != nil {
247				return nil, fmt.Errorf("cannot initialise write-ahead log %s: %w", walPath, err)
248			}
249			if err := walF.Sync(); err != nil {
250				return nil, fmt.Errorf("cannot flush write-ahead log %s: %w", walPath, err)
251			}
252		}
253	
254		walData, err := io.ReadAll(walF)
255		if err != nil {
256			return nil, fmt.Errorf("cannot read write-ahead log %s: %w", walPath, err)
257		}
258		commitData, err := io.ReadAll(commitF)
259		if err != nil {
260			return nil, fmt.Errorf("cannot read commit journal %s: %w", commitPath, err)
261		}
262		if len(walData) < headerLen || string(walData[0:8]) != walMagic {
263			return nil, fmt.Errorf("write-ahead log %s is corrupt: bad magic header", walPath)
264		}
265		version := binary.LittleEndian.Uint32(walData[8:12])
266		if version != walVersion {
267			return nil, fmt.Errorf("write-ahead log %s uses unsupported format version %d (this server supports %d)", walPath, version, walVersion)
268		}
269		if binary.LittleEndian.Uint32(walData[12:16]) != 0 {
270			return nil, fmt.Errorf("write-ahead log %s is corrupt: bad header flags", walPath)
271		}
272	
273		// Recover the committed WAL length from the fixed-width journal. A short
274		// final block is a torn append from a write that never reported success;
275		// a full block with a bad CRC is committed-data damage. Entries must chain
276		// strictly forward and never point past the WAL. For a fresh journal the
277		// committed prefix is the header itself.
278		walDurable, commitDurable := int64(headerLen), int64(0)
279		for pos := 0; pos < len(commitData); pos += commitEntry {
280			if len(commitData)-pos < commitEntry {
281				break // torn tail: discarded by the truncate below
282			}
283			block := commitData[pos : pos+commitEntry]
284			declared := int64(binary.LittleEndian.Uint64(block[0:8]))
285			if binary.LittleEndian.Uint32(block[8:12]) != commitCRC(block[0:8]) {
286				return nil, fmt.Errorf("commit journal %s is corrupt at byte %d: bad checksum (files left untouched)", commitPath, pos)
287			}
288			if declared <= walDurable || declared > int64(len(walData)) || declared < headerLen {
289				return nil, fmt.Errorf("commit journal %s is corrupt at byte %d: committed length %d is inconsistent", commitPath, pos, declared)
290			}
291			walDurable = declared
292			commitDurable = int64(pos + commitEntry)
293		}
294	
295		// Every byte the journal claims committed must form an exact chain of
296		// valid, in-range frames. Failure here is damage to acknowledged data.
297		type parsedFrame struct {
298			recType byte
299			payload []byte
300		}
301		frames := make([]parsedFrame, 0)
302		pos := headerLen
303		for int64(pos) < walDurable {
304			if pos+5 > len(walData) {
305				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: truncated frame inside committed prefix", walPath, pos)
306			}
307			length := int(binary.LittleEndian.Uint32(walData[pos : pos+4]))
308			frameLen := 5 + length + 4
309			if length > maxRecordPayload || int64(pos+frameLen) > walDurable {
310				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: frame length %d is invalid within the committed prefix", walPath, pos, length)
311			}
312			recType := walData[pos+4]
313			payload := walData[pos+5 : pos+5+length]
314			wantCRC := binary.LittleEndian.Uint32(walData[pos+5+length : pos+frameLen])
315			if crc32.Checksum(walData[pos:pos+5+length], crcTable) != wantCRC {
316				return nil, fmt.Errorf("write-ahead log %s is corrupt at byte %d: frame failed its integrity check (file left untouched)", walPath, pos)
317			}
318			if recType < recInstance || recType > recReplay {
319				return nil, fmt.Errorf("write-ahead log %s uses unsupported record type %d at byte %d", walPath, recType, pos)
320			}
321			frames = append(frames, parsedFrame{recType: recType, payload: payload})
322			pos += frameLen
323		}
324		if int64(pos) != walDurable {
325			return nil, fmt.Errorf("write-ahead log %s is corrupt: committed length %d is not a frame boundary", walPath, walDurable)
326		}
327	
328		// Rebuild relational state from the committed frames, in order.
329		store := NewStore()
330		var instanceID []byte
331		sawInstance := false
332		for i, frame := range frames {
333			switch frame.recType {
334			case recInstance:
335				if sawInstance || i != 0 {
336					return nil, fmt.Errorf("write-ahead log %s is corrupt: instance marker out of place", walPath)
337				}
338				var rec walInstance
339				if err := json.Unmarshal(frame.payload, &rec); err != nil || len(rec.InstanceID) == 0 || len(rec.InstanceID) > 64 {
340					return nil, fmt.Errorf("write-ahead log %s is corrupt: invalid instance marker: %w", walPath, err)
341				}
342				instanceID = rec.InstanceID
343				sawInstance = true
344			case recRegister, recTelemetry, recReplay:
345				if !sawInstance {
346					return nil, fmt.Errorf("write-ahead log %s is corrupt: data record precedes instance marker", walPath)
347				}
348				if err := applyRecord(store, frame.recType, frame.payload); err != nil {
349					return nil, fmt.Errorf("write-ahead log %s is corrupt: %w", walPath, err)
350				}
351			}
352		}
353	
354		// Discard unacknowledged residue: bytes from a request that never reached
355		// its journal entry (crash mid-write or a request that returned 503).
356		if int64(len(walData)) != walDurable {
357			if err := walF.Truncate(walDurable); err != nil {
358				return nil, fmt.Errorf("cannot discard unacknowledged tail of %s: %w", walPath, err)
359			}
360			if err := walF.Sync(); err != nil {
361				return nil, fmt.Errorf("cannot flush truncated %s: %w", walPath, err)
362			}
363		}
364		if int64(len(commitData)) != commitDurable {
365			if err := commitF.Truncate(commitDurable); err != nil {
366				return nil, fmt.Errorf("cannot discard torn entry of %s: %w", commitPath, err)
367			}
368			if err := commitF.Sync(); err != nil {
369				return nil, fmt.Errorf("cannot flush truncated %s: %w", commitPath, err)
370			}
371		}
372	
373		wal := &walFile{
374			walF:          walF,
375			commitF:       commitF,
376			lock:          lockFile,
377			walDurable:    walDurable,
378			commitDurable: commitDurable,
379		}
380		if !sawInstance {
381			instanceID = newInstanceID()
382			if err := wal.appendRecord(recInstance, walInstance{InstanceID: instanceID}); err != nil {
383				return nil, fmt.Errorf("cannot write instance marker to %s: %w", walPath, err)
384			}
385		}
386		// Make freshly created directory entries durable as well.
387		if dirFile, err := os.Open(dir); err != nil {
388			return nil, fmt.Errorf("cannot open data directory %s for sync: %w", dir, err)
389		} else {
390			syncErr := syscall.Fsync(int(dirFile.Fd()))
391			_ = dirFile.Close()
392			if syncErr != nil {
393				return nil, fmt.Errorf("cannot flush data directory %s: %w", dir, syncErr)
394			}
395		}
396	
397		store.wal = wal
398		store.iid = instanceID
399		committed = true
400		handedOff = true
401		return store, nil
402	}
403	
404	// Close releases the WAL files and the directory lock.
405	func (s *Store) Close() error {
406		if closer, ok := s.wal.(interface{ Close() error }); ok {
407			return closer.Close()
408		}
409		return nil
410	}
411	
412	func storageUnavailable(err error) error {
413		return fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
414	}
415	
416	func walHeader() []byte {
417		header := make([]byte, headerLen)
418		copy(header[0:8], walMagic)
419		binary.LittleEndian.PutUint32(header[8:12], walVersion)
420		return header
421	}
422	
423	// marshalFrame frames one record as
424	// [length uint32 LE][type byte][payload][crc32 LE].
425	// The CRC covers length, type and payload, so even a damaged length field of
426	// the final frame fails verification instead of masquerading as a torn tail.
427	func marshalFrame(recType byte, value any) ([]byte, error) {
428		payload, err := json.Marshal(value)
429		if err != nil {
430			return nil, err
431		}
432		if len(payload) > maxRecordPayload {
433			return nil, fmt.Errorf("wal record too large: %d bytes", len(payload))
434		}
435		frame := make([]byte, 5+len(payload)+4)
436		binary.LittleEndian.PutUint32(frame[0:4], uint32(len(payload)))
437		frame[4] = recType
438		copy(frame[5:], payload)
439		binary.LittleEndian.PutUint32(frame[5+len(payload):], crc32.Checksum(frame[:5+len(payload)], crcTable))
440		return frame, nil
441	}
442	
443	// applyRecord rebuilds in-memory state from one committed record, rejecting
444	// any structural or relational inconsistency. It never calls the clock, so
445	// recovery cannot refresh device timestamps.
446	func applyRecord(s *Store, recType byte, payload []byte) error {
447		switch recType {
448		case recRegister:
449			var rec walRegister
450			if err := json.Unmarshal(payload, &rec); err != nil {
451				return fmt.Errorf("invalid register record: %w", err)
452			}
453			if rec.ID == "" || rec.RegisteredAt.IsZero() || rec.LastSeenAt.IsZero() {
454				return errors.New("register record missing fields")
455			}
456			if _, exists := s.devices[rec.ID]; exists {
457				return fmt.Errorf("duplicate registration for device %q", rec.ID)
458			}
459			s.devices[rec.ID] = &deviceState{
460				device: Device{
461					ID:           rec.ID,
462					Site:         rec.Site,
463					RegisteredAt: rec.RegisteredAt.UTC(),
464					LastSeenAt:   rec.LastSeenAt.UTC(),
465				},
466				byEvent: make(map[string]int64),
467				batches: make(map[string]storedBatch),
468			}
469			return nil
470	
471		case recTelemetry:
472			var rec walTelemetry
473			if err := json.Unmarshal(payload, &rec); err != nil {
474				return fmt.Errorf("invalid telemetry record: %w", err)
475			}
476			state, ok := s.devices[rec.DeviceID]
477			if !ok {
478				return fmt.Errorf("telemetry for unknown device %q", rec.DeviceID)
479			}
480			if rec.Sequence != int64(len(state.events))+1 {
481				return fmt.Errorf("device %q telemetry sequence gap: got %d, want %d", rec.DeviceID, rec.Sequence, len(state.events)+1)
482			}
483			if rec.ObservedAt.IsZero() || len(rec.Values) == 0 {
484				return fmt.Errorf("device %q telemetry record missing fields", rec.DeviceID)
485			}
486			state.events = append(state.events, Event{
487				Sequence:   rec.Sequence,
488				ObservedAt: rec.ObservedAt.UTC(),
489				Values:     cloneTelemetry(rec.Values),
490			})
491			state.device.LastSeenAt = rec.ObservedAt.UTC()
492			state.device.LastTelemetry = cloneTelemetry(rec.Values)
493			return nil
494	
495		case recReplay:
496			var rec walReplay
497			if err := json.Unmarshal(payload, &rec); err != nil {
498				return fmt.Errorf("invalid replay record: %w", err)
499			}
500			state, ok := s.devices[rec.DeviceID]
501			if !ok {
502				return fmt.Errorf("replay for unknown device %q", rec.DeviceID)
503			}
504			if rec.BatchID == "" || len(rec.Samples) == 0 || len(rec.Samples) != len(rec.Receipt.SampleStatus) {
505				return fmt.Errorf("device %q replay record is incomplete", rec.DeviceID)
506			}
507			if rec.Receipt.BatchID != rec.BatchID {
508				return fmt.Errorf("device %q receipt batchId %q does not match %q", rec.DeviceID, rec.Receipt.BatchID, rec.BatchID)
509			}
510			if _, exists := state.batches[rec.BatchID]; exists {
511				return fmt.Errorf("device %q duplicate stored receipt for batch %q", rec.DeviceID, rec.BatchID)
512			}
513	
514			samples := make([]Sample, len(rec.Samples))
515			newCount, dupCount := 0, 0
516			lastNew := -1
517			for i, entry := range rec.Samples {
518				status := rec.Receipt.SampleStatus[i]
519				if entry.EventID == "" || entry.ObservedAt.IsZero() || len(entry.Values) == 0 {
520					return fmt.Errorf("device %q batch %q sample %d is incomplete", rec.DeviceID, rec.BatchID, i)
521				}
522				if status.EventID != entry.EventID {
523					return fmt.Errorf("device %q batch %q receipt/sample eventId mismatch at %d", rec.DeviceID, rec.BatchID, i)
524				}
525				samples[i] = Sample{
526					EventID:    entry.EventID,
527					ObservedAt: entry.ObservedAt.UTC(),
528					Values:     cloneTelemetry(entry.Values),
529				}
530				if sequence, seen := state.byEvent[entry.EventID]; seen {
531					existing := state.events[sequence-1]
532					if !sameInstant(existing.ObservedAt, entry.ObservedAt) || !sameValues(existing.Values, entry.Values) {
533						return fmt.Errorf("device %q dedupe record for %q disagrees with history", rec.DeviceID, entry.EventID)
534					}
535					if !status.Duplicate || status.Sequence != sequence {
536						return fmt.Errorf("device %q receipt for %q should reuse sequence %d", rec.DeviceID, entry.EventID, sequence)
537					}
538					dupCount++
539					continue
540				}
541				if status.Duplicate {
542					return fmt.Errorf("device %q receipt marks unseen event %q as duplicate", rec.DeviceID, entry.EventID)
543				}
544				want := int64(len(state.events)) + 1
545				if status.Sequence != want {
546					return fmt.Errorf("device %q batch %q sequence mismatch for %q: got %d, want %d", rec.DeviceID, rec.BatchID, entry.EventID, status.Sequence, want)
547				}
548				state.events = append(state.events, Event{
549					Sequence:   status.Sequence,
550					ObservedAt: entry.ObservedAt.UTC(),
551					Values:     cloneTelemetry(entry.Values),
552				})
553				state.byEvent[entry.EventID] = status.Sequence
554				newCount++
555				lastNew = i
556			}
557			if rec.Receipt.NewCount != newCount || rec.Receipt.Duplicate != dupCount {
558				return fmt.Errorf("device %q batch %q receipt counts disagree with samples (%d/%d vs %d/%d)",
559					rec.DeviceID, rec.BatchID, rec.Receipt.NewCount, rec.Receipt.Duplicate, newCount, dupCount)
560			}
561	
562			if newCount > 0 {
563				if rec.LastSeenAt == nil || rec.LastSeenAt.IsZero() {
564					return fmt.Errorf("device %q batch %q missing recorded receive time", rec.DeviceID, rec.BatchID)
565				}
566				if !sameValues(rec.LastTelemetry, samples[lastNew].Values) {
567					return fmt.Errorf("device %q batch %q last telemetry disagrees with last new sample", rec.DeviceID, rec.BatchID)
568				}
569				state.device.LastSeenAt = rec.LastSeenAt.UTC()
570				state.device.LastTelemetry = cloneTelemetry(rec.LastTelemetry)
571			} else if rec.LastSeenAt != nil || len(rec.LastTelemetry) != 0 {
572				return fmt.Errorf("device %q all-duplicate batch %q unexpectedly refreshed device state", rec.DeviceID, rec.BatchID)
573			}
574	
575			state.batches[rec.BatchID] = storedBatch{samples: samples, receipt: cloneReceipt(rec.Receipt)}
576			return nil
577	
578		default:
579			return fmt.Errorf("unknown record type %d", recType)
580		}
581	}
582	
583	func newInstanceID() []byte {
584		id := make([]byte, 16)
585		if _, err := rand.Read(id); err != nil {
586			panic(fmt.Sprintf("cannot generate instance id: %v", err))
587		}
588		return id
589	}
