10	
11	var (
12		ErrRuleExists      = errors.New("rule already exists")
13		ErrRuleNotFound    = errors.New("rule not found")
14		ErrAlertNotFound   = errors.New("alert not found")
15		ErrVersionConflict = errors.New("rule version conflict")
16	)
17	
18	// Close reasons recorded on an alert when it ends.
19	const (
20		// CloseReasonRecovered marks a natural recovery: a sample at or below the
21		// recovery threshold ended the alert.
22		CloseReasonRecovered = "recovered"
23		// CloseReasonRuleChanged marks an administrative close: the rule was
24		// updated, disabled or re-enabled, which ends the old version's alert.
25		CloseReasonRuleChanged = "rule-changed"
26	)
27	
28	// Rule is a per-device alerting rule. RuleID is unique within its device and
29	// immutable together with the device assignment. Version starts at 1 and
30	// increments on every successful modification; writers must present the
31	// current version, so concurrent updates on one version succeed exactly once.
32	type Rule struct {
33		RuleID    string    `json:"ruleId"`
34		Metric    string    `json:"metric"`
35		Trigger   float64   `json:"trigger"`
36		Recover   float64   `json:"recover"`
