50	// Alert is one open or resolved alert. It pins the rule version and the
51	// metric/thresholds in effect when it triggered, so later rule updates never
52	// rewrite history.
53	type Alert struct {
54		AlertID        int64        `json:"alertId"`
55		RuleID         string       `json:"ruleId"`
56		RuleVersion    int64        `json:"ruleVersion"`
57		Metric         string       `json:"metric"`
