61		Closed         bool         `json:"closed"`
62		CloseReason    string       `json:"closeReason,omitempty"`
63		ClosedAt       *time.Time   `json:"closedAt,omitempty"`
64		RecoveredBy    *AlertSample `json:"recoveredBy,omitempty"`
