66	}
67	
68	// AlertClose records how an open alert ended: naturally (Sample carries the
69	// recovery sample) or because the rule changed (ClosedAt is the server time).
70	type AlertClose struct {
71		AlertID  int64        `json:"alertId"`
72		Reason   string       `json:"reason"`
73		ClosedAt time.Time    `json:"closedAt"`
74		Sample   *AlertSample `json:"sample,omitempty"`
75	}
76	
77	// AlertFilter narrows an alert listing. Nil pointers mean "no constraint".
78	type AlertFilter struct {
79		RuleID       string
80		Closed       *bool
81		Acknowledged *bool
82	}
83	
84	func cloneAlert(alert Alert) Alert {
85		if alert.ClosedAt != nil {
86			closedAt := *alert.ClosedAt
87			alert.ClosedAt = &closedAt
88		}
89		if alert.RecoveredBy != nil {
90			recoveredBy := *alert.RecoveredBy
91			alert.RecoveredBy = &recoveredBy
92		}
93		if alert.AcknowledgedAt != nil {
94			ackedAt := *alert.AcknowledgedAt
95			alert.AcknowledgedAt = &ackedAt
96		}
97		return alert
98	}
99	
100	// --- rule CRUD --------------------------------------------------------------
101	
102	// CreateRule registers a new enabled rule at version 1.
103	func (s *Store) CreateRule(deviceID, ruleID, metric string, trigger, recoverThreshold float64) (Rule, error) {
104		s.mu.Lock()
105		defer s.mu.Unlock()
106		state, ok := s.devices[deviceID]
107		if !ok {
108			return Rule{}, ErrDeviceNotFound
109		}
110		if _, exists := state.rules[ruleID]; exists {
111			return Rule{}, ErrRuleExists
112		}
113		now := s.now().UTC()
114		rule := Rule{
115			RuleID: ruleID, Metric: metric, Trigger: trigger, Recover: recoverThreshold,
116			Enabled: true, Version: 1, CreatedAt: now, UpdatedAt: now,
117		}
118		if s.wal != nil {
119			if err := s.wal.appendRecord(recRule, walRule{DeviceID: deviceID, Rule: rule}); err != nil {
120				return Rule{}, storageUnavailable(err)
121			}
122		}
123		state.rules[ruleID] = &rule
124		return rule, nil
125	}
126	
127	// UpdateRule replaces the metric and thresholds of a rule. The presented
128	// version must match the current one; any active alert of the old version is
129	// closed with reason rule-changed and evaluation restarts with no active
130	// alert.
131	func (s *Store) UpdateRule(deviceID, ruleID, metric string, trigger, recoverThreshold float64, version int64) (Rule, error) {
132		s.mu.Lock()
133		defer s.mu.Unlock()
134		state, ok := s.devices[deviceID]
135		if !ok {
136			return Rule{}, ErrDeviceNotFound
137		}
138		rule, ok := state.rules[ruleID]
139		if !ok {
140			return Rule{}, ErrRuleNotFound
141		}
142		if rule.Version != version {
143			return Rule{}, ErrVersionConflict
144		}
145		now := s.now().UTC()
146		updated := Rule{
147			RuleID: ruleID, Metric: metric, Trigger: trigger, Recover: recoverThreshold,
148			Enabled: rule.Enabled, Version: rule.Version + 1,
149			CreatedAt: rule.CreatedAt, UpdatedAt: now,
150		}
151		return s.commitRuleChange(state, deviceID, rule, updated, now)
152	}
153	
154	// SetRuleEnabled disables or re-enables a rule. Like an update, it requires
155	// the current version, bumps it, and closes any active alert of the old
156	// version. While disabled the rule accepts telemetry but never evaluates it.
157	func (s *Store) SetRuleEnabled(deviceID, ruleID string, enabled bool, version int64) (Rule, error) {
158		s.mu.Lock()
159		defer s.mu.Unlock()
160		state, ok := s.devices[deviceID]
161		if !ok {
162			return Rule{}, ErrDeviceNotFound
163		}
164		rule, ok := state.rules[ruleID]
165		if !ok {
166			return Rule{}, ErrRuleNotFound
167		}
168		if rule.Version != version {
169			return Rule{}, ErrVersionConflict
170		}
171		now := s.now().UTC()
172		updated := *rule
173		updated.Enabled = enabled
174		updated.Version = rule.Version + 1
175		updated.UpdatedAt = now
176		return s.commitRuleChange(state, deviceID, rule, updated, now)
177	}
178	
179	// commitRuleChange persists and applies a rule mutation together with the
180	// administrative close of the old version's active alert, as one commit unit.
181	func (s *Store) commitRuleChange(state *deviceState, deviceID string, rule *Rule, updated Rule, now time.Time) (Rule, error) {
182		var closed *AlertClose
183		if activeID, has := state.active[updated.RuleID]; has {
184			closed = &AlertClose{AlertID: activeID, Reason: CloseReasonRuleChanged, ClosedAt: now}
185		}
186		if s.wal != nil {
187			if err := s.wal.appendRecord(recRule, walRule{DeviceID: deviceID, Rule: updated, Closed: closed}); err != nil {
188				return Rule{}, storageUnavailable(err)
189			}
190		}
191		*rule = updated
192		if closed != nil {
193			state.applyAlertClose(*closed)
194		}
195		return updated, nil
196	}
197	
198	func (s *Store) GetRule(deviceID, ruleID string) (Rule, error) {
199		s.mu.RLock()
200		defer s.mu.RUnlock()
201		state, ok := s.devices[deviceID]
202		if !ok {
203			return Rule{}, ErrDeviceNotFound
204		}
205		rule, ok := state.rules[ruleID]
206		if !ok {
207			return Rule{}, ErrRuleNotFound
208		}
209		return *rule, nil
210	}
211	
212	func (s *Store) ListRules(deviceID string) ([]Rule, error) {
213		s.mu.RLock()
214		defer s.mu.RUnlock()
215		state, ok := s.devices[deviceID]
216		if !ok {
217			return nil, ErrDeviceNotFound
218		}
219		rules := make([]Rule, 0, len(state.rules))
220		for _, rule := range state.rules {
221			rules = append(rules, *rule)
222		}
223		sort.Slice(rules, func(i, j int) bool { return rules[i].RuleID < rules[j].RuleID })
224		return rules, nil
225	}
226	
227	// --- alerts -----------------------------------------------------------------
228	
229	func (s *Store) GetAlert(deviceID string, alertID int64) (Alert, error) {
230		s.mu.RLock()
231		defer s.mu.RUnlock()
232		state, ok := s.devices[deviceID]
233		if !ok {
234			return Alert{}, ErrDeviceNotFound
235		}
236		if alertID < 1 || alertID > int64(len(state.alerts)) {
237			return Alert{}, ErrAlertNotFound
238		}
239		return cloneAlert(state.alerts[alertID-1]), nil
240	}
241	
242	func (s *Store) ListAlerts(deviceID string, filter AlertFilter) ([]Alert, error) {
243		s.mu.RLock()
244		defer s.mu.RUnlock()
245		state, ok := s.devices[deviceID]
246		if !ok {
247			return nil, ErrDeviceNotFound
248		}
249		alerts := make([]Alert, 0, len(state.alerts))
250		for _, alert := range state.alerts {
251			if filter.RuleID != "" && alert.RuleID != filter.RuleID {
252				continue
253			}
254			if filter.Closed != nil && alert.Closed != *filter.Closed {
255				continue
256			}
257			if filter.Acknowledged != nil && (alert.AcknowledgedAt != nil) != *filter.Acknowledged {
258				continue
259			}
260			alerts = append(alerts, cloneAlert(alert))
261		}
262		return alerts, nil
263	}
264	
265	// AckAlert acknowledges an alert. The first acknowledgement records the server
266	// time; repeating it returns the original time unchanged. Acknowledging never
267	// closes an alert and never blocks later recovery or re-triggering.
268	func (s *Store) AckAlert(deviceID string, alertID int64) (Alert, error) {
269		s.mu.Lock()
270		defer s.mu.Unlock()
271		state, ok := s.devices[deviceID]
272		if !ok {
273			return Alert{}, ErrDeviceNotFound
274		}
275		if alertID < 1 || alertID > int64(len(state.alerts)) {
276			return Alert{}, ErrAlertNotFound
277		}
278		alert := &state.alerts[alertID-1]
279		if alert.AcknowledgedAt != nil {
280			return cloneAlert(*alert), nil
281		}
282		now := s.now().UTC()
283		if s.wal != nil {
284			if err := s.wal.appendRecord(recAck, walAck{DeviceID: deviceID, AlertID: alertID, AckedAt: now}); err != nil {
285				return Alert{}, storageUnavailable(err)
286			}
287		}
288		alert.AcknowledgedAt = &now
289		return cloneAlert(*alert), nil
290	}
291	
292	// --- evaluation -------------------------------------------------------------
293	
294	// alertPlan accumulates the alert transitions caused by the accepted samples
295	// of one commit unit (a single telemetry write or one replay batch) without
296	// mutating the store. The plan is applied only after the durable commit
297	// point, so a failed write leaves no alert changes behind.
298	type alertPlan struct {
299		active map[string]int64 // ruleID -> alertID, seeded from the device state
300		nextID int64

