	s.mu.Lock()
	defer s.mu.Unlock()
	state, ok := s.devices[deviceID]
	if !ok {
		return Rule{}, ErrDeviceNotFound
	}
	rule, ok := state.rules[ruleID]
	if !ok {
		return Rule{}, ErrRuleNotFound
	}
